Sdb* process_version_definitions(ELFOBJ* bin, Elf_(Shdr)* shdr, int sz) {
    if (!shdr || sz <= 0) {
        return NULL;
    }

    Elf_(Addr) data;
    Elf_(Size) data_size;
    if (elf_getdata(bin, shdr, &data, &data_size) != 0 || data_size != sz) {
        return NULL;
    }

    Sdb* sdb = sdb_new0();
    if (!sdb) {
        return NULL;
    }

    Elf_(Word) cursor = 0;
    while (cursor < sz) {
        Elf_(Word) entry = *(Elf_(Word*)(data + cursor));
        cursor += sizeof(Elf_(Word));

        if (entry == 0) {
            break;
        }

        Elf_(Word) aux_count = *(Elf_(Word*)(data + cursor));
        cursor += sizeof(Elf_(Word));

        for (Elf_(Word) i = 0; i < aux_count; ++i) {
            char* name = (char*)(data + cursor);
            cursor += strlen(name) + 1;

            if (sdb_set(sdb, name, "1", 0) != 0) {
                sdb_free(sdb);
                return NULL;
            }
        }
    }

    return sdb;
}

Sdb* process_version_definitions(ELFOBJ *bin, Elf_(Shdr)* shdr, int sz) {
    if (!bin || !shdr || sz <= 0) {
        return NULL;
    }

    Sdb *sdb = sdb_new0();
    if (!sdb) {
        return NULL;
    }

    const char *strtab = elf_strptr(bin->elf, shdr->sh_link, 0);
    if (!strtab) {
        sdb_free(sdb);
        return NULL;
    }

    size_t offset = 0;
    while (offset < sz) {
        Elf_(Half) ndx = 0;
        char *version_name = NULL;
        int result = elf_get_version_definition(bin, shdr, offset, &ndx, &version_name);
        if (result < 0) {
            sdb_free(sdb);
            return NULL;
        }

        if (version_name) {
            char key[256];
            snprintf(key, sizeof(key), "version.%d", ndx);
            sdb_set(sdb, key, version_name, 0);
            free(version_name);
        }

        offset += result;
    }

    return sdb;
}

#include <stdlib.h>
#include <string.h>

Sdb* process_version_definitions(ELFOBJ *bin, Elf_(Shdr)* shdr, int sz) {
    if (!bin || !shdr || sz <= 0) {
        return NULL;
    }

    // Allocate memory for version definitions
    void *data = malloc(sz);
    if (!data) {
        return NULL;
    }

    // Retrieve section names and initialize an Sdb structure
    Sdb *sdb = sdb_new0();
    if (!sdb) {
        free(data);
        return NULL;
    }

    // Iterate through the version definitions
    unsigned char *ptr = (unsigned char *)data;
    unsigned char *end = ptr + sz;
    while (ptr < end) {
        Elf_(half) vdr_type = *(Elf_(half)*)ptr;
        Elf_(half) vdr_hash = *(Elf_(half)*)(ptr + 2);
        Elf_(half) vdr_aux = *(Elf_(half)*)(ptr + 4);
        Elf_(half) vdr_next = *(Elf_(half)*)(ptr + 6);

        if (vdr_type == 1) {
            // Store the version definition information in the Sdb
            char *key = "version_def";
            char *value = "definition";
            sdb_num_set(sdb, key, vdr_hash, 0);

            // Process auxiliary entries
            unsigned char *aux_ptr = ptr + vdr_aux;
            if (aux_ptr < end) {
                Elf_(half) vda_name = *(Elf_(half)*)aux_ptr;
                Elf_(half) vda_next = *(Elf_(half)*)(aux_ptr + 2);
                if (vda_name < sz) {
                    char *name = (char*)(data + vda_name);
                    sdb_set(sdb, key, name, 0);
                }
            }
        }

        ptr += vdr_next;
    }

    free(data);
    return sdb;
}

Sdb* process_version_definitions(ELFOBJ *bin, Elf_(Shdr)* shdr, int sz) {
    if (!bin || !shdr || sz <= 0) {
        return NULL;
    }

    Elf_(Versym)* verdefs = (Elf_(Versym)*)malloc(sz);
    if (!verdefs) {
        return NULL;
    }

    if (elf_get_section_names(bin, shdr, NULL, NULL) < 0) {
        free(verdefs);
        return NULL;
    }

    Sdb *sdb = sdb_new0();
    if (!sdb) {
        free(verdefs);
        return NULL;
    }

    Elf_(Versym)* vd = verdefs;
    while ((size_t)((Elf_(Byte)*)vd - (Elf_(Byte)*)verdefs) < sz) {
        if (vd->vd_ndx == 0 || vd->vd_ndx == 1) {
            vd = (Elf_(Versym)*)((Elf_(Byte)*)vd + sizeof(Elf_(Versym)));
            continue;
        }

        char *version_name = elf_strptr(bin->elf, shdr->sh_link, vd->vd_ndx);
        if (!version_name) {
            sdb_free(sdb);
            free(verdefs);
            return NULL;
        }

        char key[256];
        snprintf(key, sizeof(key), "version.%s", version_name);

        if (sdb_set(sdb, key, "1", 0) < 0) {
            sdb_free(sdb);
            free(verdefs);
            return NULL;
        }

        Elf_(Versym)* aux = (Elf_(Versym)*)((Elf_(Byte)*)vd + sizeof(Elf_(Versym)));
        while ((size_t)((Elf_(Byte)*)aux - (Elf_(Byte)*)verdefs) < sz) {
            if (aux->vd_ndx == 0) {
                break;
            }
            aux = (Elf_(Versym)*)((Elf_(Byte)*)aux + sizeof(Elf_(Versym)));
        }

        vd = aux;
    }

    free(verdefs);
    return sdb;
}

