#include "elf.h"
#include "sdb.h"

Sdb* process_version_definitions(ELFOBJ *bin, Elf_(Shdr) *shdr, int sz) {
    if (!shdr || sz <= 0) {
        return NULL;
    }

    Elf_(Half) sh_link = shdr->sh_link;
    const char *strtab = NULL;
    if (sh_link < bin->shnum && sh_link < bin->shstrndx) {
        Elf_(Shdr) *strtab_shdr = bin->shdr + sh_link;
        strtab = (const char*) bin->shdrstr;
    } else {
        return NULL;
    }

    Sdb *sdb = sdb_new0();
    if (!sdb) {
        return NULL;
    }

    const char *data = (const char*) bin->data + shdr->sh_offset;
    const char *end = data + sz;

    while (data < end) {
        Elf_(Half) len = *(Elf_(Half)*) data;
        data += sizeof(Elf_(Half));
        if (data + len > end) {
            sdb_free(sdb);
            return NULL;
        }

        const char *name = strtab + *(Elf_(Word)*) data;
        data += len;

        if (sdb_num_put(sdb, name, (uint64_t) len, NULL) == NULL) {
            sdb_free(sdb);
            return NULL;
        }

        while (data < end) {
            Elf_(Half) aux_len = *(Elf_(Half)*) data;
            data += sizeof(Elf_(Half));
            if (data + aux_len > end) {
                sdb_free(sdb);
                return NULL;
            }

            const char *aux_name = strtab + *(Elf_(Word)*) data;
            data += aux_len;

            if (sdb_num_put(sdb, aux_name, (uint64_t) aux_len, NULL) == NULL) {
                sdb_free(sdb);
                return NULL;
            }
        }
    }

    return sdb;
}
